"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  COUNTRY_RISK_SEATS,
  EQUIPMENT_REGIONS,
  EQUIP_PATH,
  GEO_SCATTER,
  HEADLINE,
  SOURCE_NOTE,
  STAGE_FLIPS,
  STACK_GEO_LAYERS,
  equipBars,
  equipPie,
  fmtBn,
  fmtPct,
  meterBars,
  riskSeatBars,
  stackGeoBars,
  type StackGeoLayer,
} from "@/data/ai-supply-chain-geography-2026-data";

// viz-types: equip bars+pie, stacked area path, stack-geo ladder bars, share??risk scatter, stage flip bars, risk-seat bars, meter compare | layout: default

type ViewId = "equipment" | "stack" | "stages" | "meters";
type EquipMetric = "share" | "billings";
type StackFilter = "all" | "upstream" | "midstream" | "downstream";
type StackMin = "0" | "70";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
